1	import { mkdir, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
2	import { basename, dirname, relative, resolve } from "node:path";
3	import { randomUUID } from "node:crypto";
4	import { canonicalJson, compareCodePoint, sha256, treeSha256 } from "./canonicalize.mjs";
5	import { fail } from "./errors.mjs";
6	import { assertArtifactIntegrity } from "./check.mjs";
7	import { buildHeadingIndex } from "./heading-index.mjs";
8	
9	const COMMON_RUNTIME_ARTIFACTS = new Map([
10	  ["scripts/runtime/common.mjs", "src/runtime/common.mjs"],
11	  ["scripts/runtime/integrity.mjs", "src/runtime/integrity.mjs"],
12	]);
13	
14	function withGeneratedMarker(entry, logicalSource) {
15	  const marker = `<!-- generated; do not edit; source: ${logicalSource}; receipt: .skill-rails-build.json -->`;
16	  if (!entry.startsWith("---\n")) fail("ENTRY_INVALID", `${logicalSource} must start with YAML frontmatter.`, "Add a closed skill frontmatter block.");
17	  const end = entry.indexOf("\n---\n", 4);
18	  if (end < 0) fail("ENTRY_INVALID", `${logicalSource} has no closing YAML frontmatter delimiter.`, "Close the frontmatter with --- on its own line.");
19	  return `${entry.slice(0, end + 5)}${marker}\n${entry.slice(end + 5)}`;
20	}
21	
22	function artifactPathForModule(id) {
23	  return `references/${id}.md`;
24	}
25	
26	function generatedTargetConfig(graph, item) {
27	  const { target } = item;
28	  return {
29	    schemaVersion: 1,
30	    packageId: graph.manifest.packageId,
31	    packageVersion: graph.manifest.packageVersion,
32	    targetId: target.targetId,
33	    mode: target.mode,
34	    imports: target.imports.map((id) => ({ id, path: artifactPathForModule(id) })),
35	    headingIndex: target.headingIndex ? `references/${target.headingIndex}.index.json` : null,
36	    fallbackReference: target.fallbackModule ? "references/fallback.md" : null,
37	    domainConfig: target.mode === "prose" ? null : "config/domain.json",
38	    domainConfigSchema: target.mode === "prose" ? null : "config/domain.schema.json",
39	    packet: target.packet ? "config/packet.json" : null,
40	    observer: target.observer ? "scripts/domain/observer.mjs" : null,
41	    renderer: target.renderer ? "scripts/domain/renderer.mjs" : null,
42	    answerContract: target.mode === "prose" ? null : `contracts/${basename(target.answerContract)}`,
43	    declaredInputs: target.declaredInputs ?? [],
44	    declaredOutput: target.declaredOutput ?? null,
45	    outputMode: target.outputMode ?? null,
46	    regionBootstrap: target.regionBootstrap ?? null,
47	  };
48	}
49	
50	function addSource(sources, id, item) {
51	  sources.push({ id, path: item.path, sha256: sha256(item.bytes) });
52	}
53	
54	export async function planTargetBuild(graph, targetId) {
55	  const item = graph.targets.get(targetId);
56	  if (!item) fail("TARGET_NOT_FOUND", `Unknown targetId: ${targetId}`, "Choose an exact targetId declared by the source package.");
57	  const artifacts = new Map();
58	  const sources = [];
59	  addSource(sources, "source-package", { path: relative(graph.rootReal, graph.manifestPath).replaceAll("\\", "/"), bytes: graph.manifestBytes });
60	  addSource(sources, `target:${targetId}`, { path: item.path, bytes: item.bytes });
61	  const entry = item.files.get("entry");
62	  addSource(sources, "entry", entry);
63	  artifacts.set("SKILL.md", Buffer.from(withGeneratedMarker(entry.text, entry.path), "utf8"));
64	
65	  for (const id of item.target.imports) {
66	    const module = graph.modules.get(id);
67	    addSource(sources, `module:${id}`, module);
68	    artifacts.set(artifactPathForModule(id), module.bytes);
69	  }
70	  if (item.target.headingIndex) {
71	    const module = graph.modules.get(item.target.headingIndex);
72	    artifacts.set(`references/${item.target.headingIndex}.index.json`, buildHeadingIndex(module));
73	  }
74	  if (item.target.fallbackModule) {
75	    const module = graph.modules.get(item.target.fallbackModule);
76	    if (!sources.some((source) => source.id === `module:${module.id}`)) addSource(sources, `module:${module.id}`, module);
77	    artifacts.set("references/fallback.md", module.bytes);
78	  }
79	
80	  artifacts.set("config/target.json", Buffer.from(`${canonicalJson(generatedTargetConfig(graph, item))}\n`, "utf8"));
81	  if (item.target.mode !== "prose") {
82	    const mappings = [
83	      ["domainConfig", "config/domain.json"],
84	      ["domainConfigSchema", "config/domain.schema.json"],
85	      ...(item.target.packet ? [["packet", "config/packet.json"]] : []),
86	      ["renderer", "scripts/domain/renderer.mjs"],
87	      ["answerContract", `contracts/${basename(item.target.answerContract)}`],
88	    ];
89	    if (item.target.observer) mappings.push(["observer", "scripts/domain/observer.mjs"]);
90	    for (const [role, destination] of mappings) {
91	      const source = item.files.get(role);
92	      addSource(sources, role, source);
93	      artifacts.set(destination, source.bytes);
94	    }
95	  }
96	
97	  const runtimeArtifacts = new Map(COMMON_RUNTIME_ARTIFACTS);
98	  runtimeArtifacts.set("scripts/run.mjs", item.target.mode === "prose" ? "src/runtime/run-check.mjs" : item.target.mode === "record-only" ? "src/runtime/run-record.mjs" : "src/runtime/run.mjs");
99	  if (item.target.mode === "prepare-record") {
100	    runtimeArtifacts.set("scripts/runtime/prepare.mjs", "src/runtime/prepare.mjs");
101	  }
102	  if (item.target.mode !== "prose") {
103	    runtimeArtifacts.set("scripts/runtime/exchange.mjs", "src/runtime/exchange.mjs");
104	    runtimeArtifacts.set("scripts/runtime/record.mjs", "src/runtime/record.mjs");
105	  }
106	  if (item.target.mode === "record-only") runtimeArtifacts.set("scripts/runtime/initialize-record.mjs", "src/runtime/initialize-record.mjs");
107	  for (const [destination, source] of runtimeArtifacts) {
108	    const bytes = await readFile(resolve(graph.repositoryRoot, source));
109	    artifacts.set(destination, bytes);
110	    addSource(sources, `runtime:${destination}`, { path: source, bytes });
111	  }
112	  const contractNames = ["build-receipt.schema.json"];
113	  if (item.target.mode !== "prose") contractNames.push("record-exchange.schema.json");
114	  if (item.target.packet) contractNames.push("packet-kernel.schema.json", "observed-facts.schema.json", "prepared-work.schema.json");
115	  for (const name of contractNames) {
116	    const sourcePath = `contracts/${name}`;
117	    const bytes = await readFile(resolve(graph.repositoryRoot, sourcePath));
118	    artifacts.set(sourcePath, bytes);
119	    addSource(sources, `contract:${name}`, { path: sourcePath, bytes });
120	  }
121	
122	  const artifactRows = [...artifacts.entries()]
123	    .sort(([left], [right]) => compareCodePoint(left, right))
124	    .map(([path, bytes]) => ({ path, sha256: sha256(bytes) }));
125	  const receipt = {
126	    schemaVersion: 1,
127	    coreVersion: graph.coreVersion,
128	    packageId: graph.manifest.packageId,
129	    packageVersion: graph.manifest.packageVersion,
130	    targetId,
131	    sources: sources.sort((a, b) => compareCodePoint(a.path, b.path) || compareCodePoint(a.id, b.id)),
132	    artifacts: artifactRows,
133	    imports: [...item.target.imports],
134	    treeSha256: treeSha256(artifacts),
135	  };
136	  return { graph, item, artifacts, receipt, receiptBytes: Buffer.from(`${canonicalJson(receipt)}\n`, "utf8") };
137	}
138	
139	async function exists(path) {
140	  try { await stat(path); return true; } catch (error) { if (error?.code === "ENOENT") return false; throw error; }
141	}
142	
143	async function materialize(plan, destination) {
144	  const exact = resolve(destination);
145	  const parent = dirname(exact);
146	  await mkdir(parent, { recursive: true });
147	  if (await exists(exact)) {
148	    await assertArtifactIntegrity(exact, "GENERATED_ARTIFACT_MODIFIED");
149	  }
150	  const token = randomUUID();
151	  const stage = resolve(parent, `.${basename(exact)}.stage-${token}`);
152	  const backup = resolve(parent, `.${basename(exact)}.backup-${token}`);
153	  try {
154	    await mkdir(stage);
155	    for (const [path, bytes] of [...plan.artifacts.entries()].sort(([a], [b]) => compareCodePoint(a, b))) {
156	      const output = resolve(stage, ...path.split("/"));
157	      await mkdir(dirname(output), { recursive: true });
158	      await writeFile(output, bytes);
159	    }
160	    await writeFile(resolve(stage, ".skill-rails-build.json"), plan.receiptBytes);
161	    await assertArtifactIntegrity(stage);
162	    if (await exists(exact)) await rename(exact, backup);
163	    try {
164	      await rename(stage, exact);
165	    } catch (error) {
166	      if (await exists(backup)) await rename(backup, exact);
167	      throw error;
168	    }
169	    await rm(backup, { recursive: true, force: true });
170	  } finally {
171	    await rm(stage, { recursive: true, force: true });
172	  }
173	  return { targetId: plan.receipt.targetId, output: exact, treeSha256: plan.receipt.treeSha256 };
174	}
175	
176	export async function buildTargets(graph, options) {
177	  const selected = options.target ? [options.target] : [...graph.targets.keys()].sort(compareCodePoint);
178	  if (options.target && !options.out) fail("ARGUMENT_INVALID", "--target requires --out.", "Provide one exact target output directory.");
179	  if (!options.target && !options.outRoot) fail("ARGUMENT_INVALID", "Building all targets requires --out-root.", "Provide the distribution root.");
180	  const plans = [];
181	  for (const targetId of selected) plans.push(await planTargetBuild(graph, targetId));
182	  const outputs = [];
183	  for (const plan of plans) {
184	    const destination = options.target ? options.out : resolve(options.outRoot, "skills", plan.receipt.targetId);
185	    outputs.push(await materialize(plan, destination));
186	  }
187	  return { schemaVersion: 1, status: "BUILT", outputs };
188	}
